"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1210],{90798:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JumpDriveConfig","desc":"Single tuning surface for the Jump Drive: bench interaction, charge values,\\nphase durations, the biome registry, and arrival rewards. Edit gameplay here,\\nnever in manager or controller code.\\n\\nStudio setup required:\\n  1. Tag one Model `JumpDriveBench` with its PrimaryPart set.\\n  2. Give it a BasePart `JumpPromptPart` holding a ProximityPrompt (opens the GUI).\\n  3. Give it a BasePart `DepositPromptPart` holding a ProximityPrompt (feeds Energy tools).\\n  4. Tag one BasePart `WormholeAnchor` marking where the black hole appears.\\n  5. Create `ReplicatedStorage/JumpDriveVfx` holding Models `Wormhole` and `Lightspeed`.\\n  6. Create `ReplicatedStorage/GuiAssets/JumpDriveGui` and `.../JumpVoteBanner` (see plan Task 11).","source":{"line":18,"path":"src/ReplicatedStorage/SharedModules/Configs/JumpDriveConfig.luau"}}')}}]);